void ConstructSphereBoxOneShotManifold(const FSphere& Sphere, const FRigidTransform3& SphereTransform, const FImplicitBox3& Box, const FRigidTransform3& BoxTransform, const FReal Dt, FPBDCollisionConstraint& Constraint)
{
	// We only build one shot manifolds once
	// All convexes are pre-scaled, or wrapped in TImplicitObjectScaled
	ensure(SphereTransform.GetScale3D() == FVec3(1.0f, 1.0f, 1.0f));
	ensure(BoxTransform.GetScale3D() == FVec3(1.0f, 1.0f, 1.0f));

	// @todo(chaos): support manifold maintenance
	Constraint.ResetActiveManifoldContacts();

	FContactPoint ContactPoint = SphereBoxContactPoint(Sphere, SphereTransform, Box, BoxTransform);
	if (ContactPoint.Phi < Constraint.GetCullDistance())
	{
		Constraint.AddOneshotManifoldContact(ContactPoint);
	}
}

FContactPoint SphereBoxContactPoint(const FSphere& Sphere, const FRigidTransform3& SphereTransform, const FImplicitBox3& Box, const FRigidTransform3& BoxTransform)
{
	FContactPoint Result;


	const FVec3 SphereWorld = SphereTransform.TransformPosition(FVec3(Sphere.GetCenterf()));	// World-space sphere pos
	const FVec3 SphereBox = BoxTransform.InverseTransformPosition(SphereWorld);			// Box-space sphere pos

	FVec3 NormalBox;																	// Box-space normal
	FReal PhiToSphereCenter = Box.PhiWithNormal(SphereBox, NormalBox);
	FReal Phi = PhiToSphereCenter - Sphere.GetRadiusf();

	FVec3 NormalWorld = BoxTransform.TransformVectorNoScale(NormalBox);
	FVec3 LocationWorld = SphereWorld - (Sphere.GetRadiusf()) * NormalWorld;

	Result.ShapeContactPoints[0] = SphereTransform.InverseTransformPosition(LocationWorld);
	Result.ShapeContactPoints[1] = BoxTransform.InverseTransformPosition(LocationWorld - Phi * NormalWorld);
	Result.ShapeContactNormal = NormalBox;
	Result.Phi = Phi;
	return Result;
}

